.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-md); height:var(--p-icon-md); flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:calc(var(--p-space-unit) * 5); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }

.ds .ds-input { display:block; width:100%; min-width:0; min-height:var(--p-control-size-md); padding:var(--p-space-sm) var(--p-space-md); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-control-radius); background:var(--p-bg); box-shadow:var(--p-inset); color:var(--p-ink); font-size:var(--p-text-body); line-height:var(--p-leading-normal); }
.ds .ds-input::placeholder { color:var(--p-muted); opacity:var(--p-opacity-full); }
.ds .ds-input:disabled { opacity:var(--p-opacity-full); box-shadow:none; color:var(--p-muted); background:var(--p-disabled); border-color:var(--p-line); cursor:not-allowed; }
.ds .ds-input[aria-invalid="true"] { border-color:var(--p-error); border-width:var(--p-border-width-strong); padding:var(--p-space-xs) var(--p-space-sm); }
.ds label.ds-field { display:grid; gap:var(--p-space-xs); min-width:0; font-size:var(--p-text-body); }
/* looks: the same selector draws a bare input and the input inside a field of that look */
.ds :is(.ds-input[data-look],.ds-field[data-look] .ds-input):disabled { background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); box-shadow:none; }
.ds :is(.ds-input[data-look],.ds-field[data-look] .ds-input)[aria-invalid="true"] { border-color:var(--p-error); }
/* looks: the helper a value needs sits inside the same box — clear, unit, − and +, or show */
.ds .ds-input-group { display:flex; align-items:center; min-width:0; border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-control-radius); background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-input-group:focus-within { border-color:var(--p-accent); box-shadow:0 0 0 var(--p-border-width) var(--p-accent); }
.ds .ds-input-group > .ds-input { flex:1 1 0; min-height:var(--p-control-size-md); border:0; border-radius:inherit; background:transparent; box-shadow:none; }
.ds .ds-input-group > .ds-input:focus-visible { outline:none; }
.ds .ds-input-tool { display:grid; place-items:center; flex:none; width:var(--p-control-size-sm); height:var(--p-control-size-sm); padding:0; border:0; border-radius:calc(var(--p-control-radius) - var(--p-radius-xs)); background:transparent; color:var(--p-ink); font:var(--p-weight-medium) var(--p-text-lg)/var(--p-leading-none) var(--p-font); cursor:pointer; }
.ds .ds-input-tool:hover:not(:disabled) { background:var(--p-surface); }
.ds .ds-input-tool:focus-visible { outline-offset:calc(var(--p-focus-offset) * -1); }
.ds .ds-input-group[data-look="clear"] > .ds-input:placeholder-shown + .ds-input-tool { visibility:hidden; }
.ds .ds-input-group[data-look="unit"] > .ds-input { text-align:right; font-variant-numeric:tabular-nums; }
.ds .ds-input-unit { flex:none; align-self:stretch; min-height:var(--p-control-size-sm); padding:0 var(--p-space-sm); border:0; border-left:var(--p-border-width) solid var(--p-line); border-radius:0 var(--p-control-radius) var(--p-control-radius) 0; background:transparent; color:var(--p-ink); font:inherit; font-weight:var(--p-weight-semibold); }
.ds .ds-input-unit:focus-visible { outline-offset:calc(var(--p-focus-offset) * -1); }
.ds .ds-input-group[data-look="stepper"] { width:fit-content; }
.ds .ds-input-group[data-look="stepper"] > .ds-input { flex:0 0 var(--p-control-size-xl); padding-inline:var(--p-space-2xs); text-align:center; font-variant-numeric:tabular-nums; -moz-appearance:textfield; appearance:textfield; }
.ds .ds-input-group[data-look="stepper"] > .ds-input::-webkit-inner-spin-button { -webkit-appearance:none; margin:0; }
.ds .ds-input-group:has(:disabled) { background:var(--p-disabled); border-color:var(--p-line); box-shadow:none; color:var(--p-muted); }
.ds .ds-input-group:has(:disabled) .ds-input-tool { color:var(--p-muted); cursor:not-allowed; }
.ds .ds-input-group:has([aria-invalid="true"]) { border-color:var(--p-error); box-shadow:0 0 0 var(--p-border-width) var(--p-error); }
/* reveal: the text button stays inside the box so the typed secret can be checked without retyping */
.ds .ds-input-group[data-look="reveal"] .ds-input-tool { width:auto; min-width:var(--p-control-size-sm); padding:0 var(--p-space-sm); color:var(--p-accent); font-size:var(--p-text-body); font-weight:var(--p-weight-semibold); }

'use client';
import React, { useState } from 'react';
export function Input({ look, className = '', ...props }) { return <input {...props} className={`ds-input ${className}`} data-look={look} />; }
// The clear, unit and stepper looks keep the helper inside the same box:
// <InputGroup look="clear"><Input /><InputTool aria-label="지우기">…</InputTool></InputGroup>
export function InputGroup({ look, children, ...props }) { return <span {...props} className="ds-input-group" data-look={look}>{children}</span>; }
export function InputTool({ children, ...props }) { return <button type="button" {...props} className="ds-input-tool">{children}</button>; }
// The field row look joins a start and an end value in one box with this mark between them.
// The reveal look flips the typed secret to plain text in place, so a typo is seen instead of retyped.
export function PasswordInput({ label = '비밀번호', disabled, ...props }) {
  const [shown, setShown] = useState(false);
  return <InputGroup look="reveal"><Input {...props} disabled={disabled} type={shown ? 'text' : 'password'} /><InputTool aria-label={`${label} ${shown ? '숨기기' : '보기'}`} disabled={disabled} onClick={() => setShown(!shown)}>{shown ? '숨기기' : '보기'}</InputTool></InputGroup>;
}
export function InputJoin({ children = '~' }) { return <span className="ds-input-join" aria-hidden="true">{children}</span>; }

